        '**铁律二：比较器必须满足严格弱序，相等时必须返回 false。** 写成 `return a.score <= b.score;` 会让 `cmp(a, b)` 和 `cmp(b, a)` 同时为真，libstdc++ 的内省排序在插入排序阶段会越过哨兵一路读到数组外面，轻则顺序错乱，重则直接段错误。这个 bug 在小数据下往往不复现，一到大数据就崩。',
