        x: `from functools import cmp_to_key

# 其它语言可能要在普通排序 / 稳定排序之间做选择，Python 不用：
# sorted() 和 list.sort() 用的都是 Timsort，稳定性是语言规范写死的保证
recs = [('ann', 90), ('bob', 90), ('cid', 80)]

# 只按分数降序：同为 90 分的 ann、bob 保持输入顺序 · 稳定排序 免费拿到
by_score = sorted(recs, key=lambda r: -r[1])
print(' '.join(name for name, _ in by_score))     # ann bob cid

# 复合规则「分数降序、同分按名字升序」的两种惯用写法，结果一致：
# 写法一：key 元组一次排完 · 数值取负实现降序，字符串保持原样即升序
plan_a = sorted(recs, key=lambda r: (-r[1], r[0]))

# 写法二：两轮排序 · 先排次关键字，再排主关键字，靠稳定性把规则叠上去
# 字符串没法取负，遇到「名字要降序」这类需求时，两轮排序就是标准解法
plan_b = sorted(recs, key=lambda r: r[0])         # 第一轮：名字升序
plan_b.sort(key=lambda r: r[1], reverse=True)     # 第二轮：分数降序，同分不乱

print(plan_a == plan_b)                           # True：两种写法答案相同

# 实在需要传统比较器时用 cmp_to_key 兜底；能用 key 就别用它，更慢
def cmp(a, b):
    return (b[1] - a[1]) or (a[0] > b[0]) - (a[0] < b[0])

print(sorted(recs, key=cmp_to_key(cmp)) == plan_a)    # True`,
