    lede: '公开的华为机考备考指南把 DFS / BFS 的重要度标成「极高」，并注明「华为非常爱考图论」。这份专项把网格搜索的模板、30 秒选型判断和三个必踩的坑一次讲透，再用 12 道题从「能不能走到」一路练到数独回溯。',
